/// This set describes shutdown/drain progress, pending control backlogs, and
/// the state and throughput of the runtime-managed timer machinery. It is the
/// primary metric set for understanding whether the pipeline runtime is still
/// making progress under control-plane load and where graceful shutdown is
/// spending time.
#[metric_set(name = "pipeline.runtime_control")]
#[derive(Debug, Default, Clone)]
pub(crate) struct RuntimeControlMetrics {
    /// Whether the runtime is currently in graceful drain mode.
    ///
    /// This is the top-level liveness phase signal for shutdown analysis: `1`
    /// means ingress has been stopped and the runtime is trying to converge to
    /// quiescence, `0` means normal operation.
    ///
    /// Level: `basic`.
    #[metric(unit = "{1}")]
    pub drain_active: Gauge<u64>,
    /// Number of receivers that still need to report `ReceiverDrained`.
    ///
    /// This shows whether shutdown is still blocked in the receiver-first drain
    /// phase and helps identify a stuck or slow receiver delaying downstream
    /// shutdown.
    ///
    /// Level: `basic`.
    #[metric(name = "drain.pending_receivers", unit = "{node}")]
    pub drain_pending_receivers: Gauge<u64>,
    /// Number of node-control deliveries currently buffered for later retry.
    ///
    /// A sustained non-zero value indicates the runtime manager is no longer
    /// delivering control work immediately and is absorbing backpressure from
    /// full node-control inboxes instead of blocking the runtime.
    ///
    /// Level: `basic`.
    #[metric(name = "pending_sends.buffered", unit = "{message}")]
    pub pending_sends_buffered: Gauge<u64>,
    /// Number of ordinary per-node timers currently registered.
    ///
    /// This is useful for understanding timer pressure and for spotting leaks
    /// where timers are started but not canceled or consumed as expected.
    ///
    /// Level: `basic`.
    #[metric(unit = "{timer}")]
    pub timers_active: Gauge<u64>,
    /// Number of telemetry collection timers currently registered.
    ///
    /// This distinguishes telemetry scheduling pressure from normal timer
    /// traffic and helps explain unexpected `CollectTelemetry` activity.
    ///
    /// Level: `basic`.
    #[metric(name = "telemetry_timers.active", unit = "{timer}")]
    pub telemetry_timers_active: Gauge<u64>,
    /// Count of `RuntimeControlMsg::Shutdown` requests accepted by this runtime.
    ///
    /// This marks the start of the runtime-managed drain sequence and is the
    /// main counter used to correlate later drain-phase transitions.
    ///
    /// Level: `normal`.
    #[metric(unit = "{message}")]
    pub shutdown_received: Counter<u64>,
    /// Count of `DrainIngress` fan-out operations sent to receivers.
    ///
    /// This confirms that shutdown moved from "requested" to "stop admitting
    /// new ingress", which is the first active liveness step of graceful drain.
    ///
    /// Level: `normal`.
    #[metric(name = "drain_ingress.sent", unit = "{message}")]
    pub drain_ingress_sent: Counter<u64>,
    /// Count of `ReceiverDrained` notifications received from receivers.
    ///
    /// This shows actual receiver-side drain progress and helps distinguish "no
    /// work admitted anymore" from "receivers have really finished draining".
    ///
    /// Level: `normal`.
    #[metric(name = "receiver_drained.received", unit = "{message}")]
    pub receiver_drained_received: Counter<u64>,
    /// Count of downstream `Shutdown` fan-out operations to non-receivers.
    ///
    /// This marks the handoff from receiver draining to downstream convergence,
    /// which is useful when debugging where shutdown latency is spent.
    ///
    /// Level: `normal`.
    #[metric(name = "downstream_shutdown.sent", unit = "{message}")]
    pub downstream_shutdown_sent: Counter<u64>,
    /// Count of shutdowns that reached the deadline before natural completion.
    ///
    /// Any non-zero value here is a direct signal that graceful drain did not
    /// complete in time and that liveness relied on the shutdown deadline.
    ///
    /// Level: `normal`.
    #[metric(name = "shutdown.deadline_forced", unit = "{message}")]
    pub shutdown_deadline_forced: Counter<u64>,
    /// Count of `StartTimer` control messages received by the runtime manager.
    ///
    /// This helps quantify timer creation pressure and can explain growth in
    /// `timers.active` or bursts of later `timer_tick.sent` activity.
    ///
    /// Level: `normal`.
    #[metric(name = "start_timer.received", unit = "{message}")]
    pub start_timer_received: Counter<u64>,
    /// Count of `CancelTimer` control messages received by the runtime manager.
    ///
    /// Comparing this with timer starts helps diagnose timer churn, leaks, or
    /// mismatches between node scheduling and node cleanup behavior.
    ///
    /// Level: `normal`.
    #[metric(name = "cancel_timer.received", unit = "{message}")]
    pub cancel_timer_received: Counter<u64>,
    /// Count of telemetry timer start requests received by the runtime manager.
    ///
    /// This shows how much of the runtime-control stream is driven by metrics
    /// collection scheduling rather than ordinary data-plane coordination.
    ///
    /// Level: `normal`.
    #[metric(name = "start_telemetry_timer.received", unit = "{message}")]
    pub start_telemetry_timer_received: Counter<u64>,
    /// Count of telemetry timer cancel requests received by the runtime manager.
    ///
    /// This is mainly useful for checking that telemetry scheduling remains
    /// bounded and does not accumulate stale per-node timers.
    ///
    /// Level: `normal`.
    #[metric(name = "cancel_telemetry_timer.received", unit = "{message}")]
    pub cancel_telemetry_timer_received: Counter<u64>,
    /// Count of `TimerTick` control messages sent to nodes.
    ///
    /// This confirms that due timers are actually being delivered and helps
    /// detect starvation where timers accumulate but ticks do not make progress.
    ///
    /// Level: `normal`.
    #[metric(name = "timer_tick.sent", unit = "{message}")]
    pub timer_tick_sent: Counter<u64>,
    /// Count of `CollectTelemetry` control messages sent to nodes.
    ///
    /// This helps confirm telemetry timers are progressing under load and that
    /// observability work is not being starved by other runtime-control traffic.
    ///
    /// Level: `normal`.
    #[metric(name = "collect_telemetry.sent", unit = "{message}")]
    pub collect_telemetry_sent: Counter<u64>,
    /// Distribution of time spent waiting for receivers to finish draining.
    ///
    /// This isolates the receiver-gated phase of shutdown and is useful for
    /// determining whether slow graceful shutdown is ingress-bound or further
    /// downstream in the pipeline.
    ///
    /// Level: `detailed`.
    #[metric(name = "drain.receiver_phase_duration_ns", unit = "ns")]
    pub drain_receiver_phase_duration_ns: Mmsc,
    /// Distribution of total graceful shutdown duration for the runtime.
    ///
    /// This is the top-level latency metric for shutdown liveness and shows how
    /// long the runtime took to move from shutdown acceptance to completion or
    /// forced deadline exit.
    ///
    /// Level: `detailed`.
    #[metric(name = "drain.total_duration_ns", unit = "ns")]
    pub drain_total_duration_ns: Mmsc,
}

/// Tokio runtime metrics sampled from the pipeline thread.
///
/// These metrics are collected from `tokio::runtime::Handle::try_current` / `Handle::metrics()`
/// and are updated at the same cadence as `PipelineMetrics`.
///
/// **Notes**
/// - Tokio exposes runtime-level (aggregate) metrics; it does not expose per-task numeric
/// metrics through the stable API.
/// - Some Tokio metrics are per-worker; this metric set reports aggregates across all workers.
/// - When compiled without `tokio_unstable`, only Tokio's stable metrics are included.
/// Additional metrics are included when compiling with `RUSTFLAGS="--cfg tokio_unstable" cargo build --release`.
#[metric_set(name = "tokio.runtime")]
#[derive(Debug, Default, Clone)]
pub struct TokioRuntimeMetrics {
    /// Number of worker threads used by the Tokio runtime.
    ///
    /// For Tokio's `current_thread` runtime, this is always `1`.
    #[metric(unit = "{thread}")]
    pub worker_count: ObserveUpDownCounter<u64>,
    /// Current number of alive tasks in the runtime.
    ///
    /// This value increases when tasks are spawned and decreases when tasks complete.
    #[metric(unit = "{task}")]
    pub task_active_count: ObserveUpDownCounter<u64>,
    /// Current number of tasks pending in the runtime's global/injection queue.
    ///
    /// This queue is used when tasks are spawned or woken from outside the runtime.
    #[metric(unit = "{task}")]
    pub global_task_queue_size: ObserveUpDownCounter<u64>,
    /// Total worker busy time, summed across all runtime workers, since runtime creation.
    ///
    /// With multiple workers, this sum can exceed wall-clock time because workers can be busy
    /// concurrently. This metric is only available on targets with 64-bit atomics.
    #[cfg(target_has_atomic = "64")]
    #[metric(unit = "{s}")]
    pub worker_busy_time: ObserveCounter<f64>,
    /// Total number of times runtime workers parked, summed across all workers, since runtime creation.
    ///
    /// A worker "parks" when it becomes idle and waits for new work.
    /// This metric is only available on targets with 64-bit atomics.
    #[cfg(target_has_atomic = "64")]
    #[metric(unit = "{park}")]
    pub worker_park_count: ObserveCounter<u64>,
    /// Total number of park/unpark transitions, summed across all workers, since runtime creation.
    ///
    /// An odd value means at least one worker is currently parked; an even value means all workers
    /// are currently active. This metric is only available on targets with 64-bit atomics.
    #[cfg(target_has_atomic = "64")]
    #[metric(unit = "{unpark}")]
    pub worker_park_unpark_count: ObserveCounter<u64>,
    /// Current number of tasks pending in the blocking thread pool.
    ///
    /// This counts tasks spawned using `spawn_blocking` that have not yet started.
    #[cfg(tokio_unstable)]
    #[metric(unit = "{task}")]
    pub blocking_task_queue_size: ObserveUpDownCounter<u64>,
    /// Current number of threads created for the blocking thread pool.
    #[cfg(tokio_unstable)]
    #[metric(unit = "{thread}")]
    pub blocking_thread_count: ObserveUpDownCounter<u64>,
    /// Current number of idle threads in the blocking thread pool.
    #[cfg(tokio_unstable)]
    #[metric(unit = "{thread}")]
    pub blocking_thread_idle_count: ObserveUpDownCounter<u64>,
    /// Current number of tasks pending in worker-local queues, summed across all workers.
    #[cfg(tokio_unstable)]
    #[metric(unit = "{task}")]
    pub worker_local_queue_size: ObserveUpDownCounter<u64>,
    /// Total number of tasks spawned in the runtime since it was created.
    ///
    /// This counter is monotonically increasing. This metric requires `tokio_unstable` and
    /// 64-bit atomics.
    #[cfg(all(tokio_unstable, target_has_atomic = "64"))]
    #[metric(unit = "{spawn}")]
    pub spawned_tasks_count: ObserveCounter<u64>,
    /// Total number of tasks scheduled from outside the runtime since it was created.
    ///
    /// These schedules go through the global injection queue and can be slower than worker-local scheduling.
    /// This metric requires `tokio_unstable` and 64-bit atomics.
    #[cfg(all(tokio_unstable, target_has_atomic = "64"))]
    #[metric(unit = "{remote}")]
    pub remote_schedule_count: ObserveCounter<u64>,
    /// Total number of times tasks were forced to yield after exhausting their cooperative budget.
    ///
    /// This metric requires `tokio_unstable` and 64-bit atomics.
    #[cfg(all(tokio_unstable, target_has_atomic = "64"))]
    #[metric(unit = "{yield}")]
    pub budget_forced_yield_count: ObserveCounter<u64>,
    /// Total number of "noop" unpark events, summed across workers, since runtime creation.
    ///
    /// A noop unpark is when a worker is unparked but finds no work before parking again.
    /// This metric requires `tokio_unstable` and 64-bit atomics.
    #[cfg(all(tokio_unstable, target_has_atomic = "64"))]
    #[metric(unit = "{noop}")]
    pub worker_noop_count: ObserveCounter<u64>,
    /// Total number of successful steal operations, summed across workers, since runtime creation.
    ///
    /// This metric requires `tokio_unstable` and 64-bit atomics.
    #[cfg(all(tokio_unstable, target_has_atomic = "64"))]
    #[metric(unit = "{steal}")]
    pub worker_steal_success_count: ObserveCounter<u64>,
    /// Total number of steal attempts, summed across workers, since runtime creation.
    ///
    /// This metric requires `tokio_unstable` and 64-bit atomics.
    #[cfg(all(tokio_unstable, target_has_atomic = "64"))]
    #[metric(unit = "{steal}")]
    pub worker_steal_attempt_count: ObserveCounter<u64>,
    /// Total number of task polls, summed across workers, since runtime creation.
    ///
    /// This metric requires `tokio_unstable` and 64-bit atomics.
    #[cfg(all(tokio_unstable, target_has_atomic = "64"))]
    #[metric(unit = "{poll}")]
    pub worker_poll_count: ObserveCounter<u64>,
    /// Total number of tasks scheduled onto worker-local queues, summed across workers, since runtime creation.
    ///
    /// This metric requires `tokio_unstable` and 64-bit atomics.
    #[cfg(all(tokio_unstable, target_has_atomic = "64"))]
    #[metric(unit = "{schedule}")]
    pub worker_local_schedule_count: ObserveCounter<u64>,
    /// Total number of worker local-queue overflows, summed across workers, since runtime creation.
    ///
    /// This metric only applies to Tokio's multi-threaded scheduler. This metric requires
    /// `tokio_unstable` and 64-bit atomics.
    #[cfg(all(tokio_unstable, target_has_atomic = "64"))]
    #[metric(unit = "{overflow}")]
    pub worker_overflow_count: ObserveCounter<u64>,
    /// Total number of file descriptors registered with the runtime's I/O driver.
    ///
    /// This metric requires `tokio_unstable` and 64-bit atomics (and Tokio's `net` feature).
    #[cfg(all(tokio_unstable, target_has_atomic = "64"))]
    #[metric(unit = "{fd}")]
    pub io_driver_fd_registered_count: ObserveCounter<u64>,
    /// Total number of file descriptors deregistered from the runtime's I/O driver.
    ///
    /// This metric requires `tokio_unstable` and 64-bit atomics (and Tokio's `net` feature).
    #[cfg(all(tokio_unstable, target_has_atomic = "64"))]
    #[metric(unit = "{fd}")]
    pub io_driver_fd_deregistered_count: ObserveCounter<u64>,
    /// Total number of ready events processed by the runtime's I/O driver.
    ///
    /// This metric requires `tokio_unstable` and 64-bit atomics (and Tokio's `net` feature).
    #[cfg(all(tokio_unstable, target_has_atomic = "64"))]
    #[metric(unit = "{ready}")]
    pub io_driver_ready_count: ObserveCounter<u64>,
    /// Whether Tokio task poll-time histogram collection is enabled.
    ///
    /// Reported as `1` when enabled and `0` otherwise.
    /// This metric requires `tokio_unstable` and 64-bit atomics.
    #[cfg(all(tokio_unstable, target_has_atomic = "64"))]
    #[metric(unit = "{1}")]
    pub poll_time_histogram_enabled: ObserveUpDownCounter<u64>,
}
